const { chromium } = require('C:/Users/human-01/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const fs = require('node:fs');
const assert = require('node:assert/strict');
(async () => {
  const draft=JSON.parse(fs.readFileSync('data-collection/wegovy/rag/cache/nutrition/verified-draft.json','utf8'));
  const current=new Date();current.setDate(current.getDate()-(current.getDay()+6)%7);
  const date=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const offset=(new Date(date(current)+'T12:00:00')-new Date(draft.preferences.weekStart+'T12:00:00'))/86400000;
  draft.preferences.weekStart=date(current);
  for(const e of draft.events) for(const field of ['start','end']) {const d=new Date(e[field]);d.setDate(d.getDate()+offset);e[field]=date(d)+e[field].slice(10);}
  for (const e of draft.events) if(e.kind==='MEAL') e.foodEvidence={servingWeight:'300',nutrition:{INFO_ENG:'400',INFO_CAR:'62.5',INFO_PRO:'15',INFO_FAT:'10',INFO_NA:''}};
  const snacks=JSON.parse(fs.readFileSync('stevil-backend/src/main/resources/planner/snacks.json','utf8'));
  let conflict=false; let saved={revision:1,preferences:draft.preferences,events:draft.events};
  const browser=await chromium.launch({headless:true,channel:'msedge'});
  try {
    const page=await browser.newPage({viewport:{width:1440,height:1100}});const errors=[];
    page.on('pageerror',e=>{errors.push(e.message);console.log('PAGE ERROR',e.message);});
    await page.route(/\/src\/main\.jsx(?:\?.*)?$/,route=>route.fulfill({contentType:'application/javascript',body:`import '/src/__check-shared.jsx';`}));
    await page.route(/^http:\/\/127\.0\.0\.1:3001\/api\//,async route=>{
      const request=route.request(),url=new URL(request.url());
      if(url.pathname.endsWith('/snacks')) return route.fulfill({json:snacks});
      if(url.pathname.endsWith('/profile'))return route.fulfill({json:{weightKg:null}});
      if(request.method()==='PUT' && conflict) return route.fulfill({status:409,json:{message:'conflict'}});
      if(request.method()==='PUT'){saved={...request.postDataJSON(),revision:saved.revision+1};}
      return route.fulfill({json:saved});
    });
    await page.goto('http://127.0.0.1:3001/');
    const planner=page.locator('.weekly-planner');
    await planner.locator('.planner-event--meal').first().waitFor({timeout:10000}).catch(async e=>{console.log('BODY',await page.locator('body').innerText());throw e;});
    await planner.locator('.planner-snack-suggestion').first().click();
    const panels=page.locator('.saved-plan-panel');
    await panels.nth(0).locator('input[type=date]').fill(saved.preferences.weekStart);
    await panels.nth(1).locator('input[type=date]').fill(saved.preferences.weekStart);
    const offer=planner.getByRole('region',{name:'unused'});
    await planner.locator('.planner-snack-offer').waitFor();
    assert.match(await planner.locator('.planner-snack-offer').innerText(),/25.0g 부족/);
    assert.equal(await planner.locator('.planner-event--snack').count(),0);
    await page.setViewportSize({width:390,height:844});
    await planner.locator('.planner-snack-offer').screenshot({path:'data-collection/wegovy/rag/cache/nutrition/snack-offer-mobile.png'});
    await planner.getByRole('button',{name:/간식으로 추가$/}).first().click();
    assert.equal(await planner.locator('.planner-event--snack').count(),1);
    assert.equal(await planner.locator('.planner-snack-offer').count(),0);
    assert.equal(await planner.locator('.planner-meal-components > details').count(),1);
    await planner.locator('.planner-event--snack input').check();
    assert.match(await planner.locator('.planner-nutrition-cards > div').nth(2).innerText(),/1\s*\/ 4건/);
    await planner.getByRole('button',{name:'확정하고 저장'}).click();
    await page.waitForFunction(()=>document.querySelectorAll('.saved-plan-panel')[0]?.querySelectorAll('article').length===4);
    const foodPanel=panels.nth(0), exercisePanel=panels.nth(1);
    assert.equal(await foodPanel.locator('article').count(),4);
    const snackRow=foodPanel.locator('article').filter({has:page.locator('.saved-plan-time small', {hasText:'간식'})});
    await snackRow.locator('input').click();
    await page.waitForFunction(()=>!document.querySelector('.planner-event--snack input')?.checked);
    assert.equal(saved.events.find(e=>e.kind==='SNACK').completed,false);
    assert.equal(await exercisePanel.locator('article').count(),saved.events.filter(e=>e.kind==='EXERCISE'&&e.start.startsWith(saved.preferences.weekStart)).length);
    await exercisePanel.locator('input[type=checkbox]').first().click();
    await page.waitForFunction(()=>document.querySelector('.planner-event--exercise input')?.checked);
    conflict=true;
    await snackRow.locator('input').click();
    await foodPanel.getByRole('alert').waitFor();
    assert.equal(await snackRow.locator('input').isChecked(),false);
    conflict=false;
    await foodPanel.getByRole('button',{name:'다시 불러오기'}).click();
    await foodPanel.locator('article').first().waitFor();
    await snackRow.locator('input').click();
    await page.waitForFunction(()=>document.querySelector('.planner-event--snack input')?.checked);
    await foodPanel.screenshot({path:'data-collection/wegovy/rag/cache/nutrition/shared-plan-mobile.png'});
    await page.reload();
    await planner.locator('.planner-event--snack').waitFor();
    assert.equal(await planner.locator('.planner-event--snack input').isChecked(),true);
    assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1),false);
    assert.deepEqual(errors,[]);
    console.log('PASS: shared food/snack/exercise views, bidirectional completion refresh, conflict preserves state; optional snack recommendation, add between meals, count nutrients only after choice, completion and mocked save/reload, mobile layout');
  } finally {await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
